/* ===================== BÀI 5 · Thanh ghi tổng quát và con trỏ ===================== */
/* Bài 5 · Thanh ghi tổng quát và con trỏ (AMTS-EMB-002-M02-L01, X86-005) — sinh bởi tools/author/mpu8086/l05.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P5=[{"label": "Ví dụ: AH và AL là hai nửa của AX", "code": "; Ví dụ 1: AH và AL là hai nửa của AX\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq1     DW      ?                       ; AX sau khi đổi AL\nkq2     DW      ?                       ; AX sau khi đổi AH\nnua     DB      ?                       ; một nửa chép sang CL\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 1234H               ; AH = 12h, AL = 34h\n        MOV     AL, 0ABH                ; chỉ đổi byte thấp: AX = 12ABh\n        MOV     kq1, AX\n        MOV     AH, 0CDH                ; chỉ đổi byte cao: AX = CDABh\n        MOV     kq2, AX\n        MOV     BX, AX                  ; chép 16 bit: BH = CDh, BL = ABh\n        MOV     CL, BH                  ; chép một nửa: CL = CDh\n        MOV     nua, CL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước và nhìn phần Thanh ghi: sau MOV AL, 0ABh chỉ AL đổi màu, AX = 12ABh; sau MOV AH, 0CDh chỉ AH đổi, AX = CDABh. MOV BX, AX chép cả 16 bit; MOV CL, BH chép một nửa. Phần Bộ nhớ: kq1, kq2, nua. Đoán trước: sau MOV AH, 0CDh, AX bằng bao nhiêu? Đáp án CDABh."}, {"label": "Bẫy: INC AL không nhớ sang AH", "code": "; Bẫy: INC AL không nhớ sang AH\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nsau8    DW      ?                       ; AX sau INC AL\nsau16   DW      ?                       ; AX sau INC AX\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 00FFH               ; AH = 00h, AL = FFh\n        INC     AL                      ; phép tính 8 bit: AL quay về 00h\n        MOV     sau8, AX                ; AX = 0000h, không phải 0100h\n        MOV     AX, 00FFH\n        INC     AX                      ; phép tính 16 bit trên cả AX\n        MOV     sau16, AX               ; AX = 0100h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: INC AL làm AL = FFh thành 00h nhưng không cộng sang AH, nên AX = 0000h chứ không phải 0100h. INC AX tính trên cả 16 bit cho 0100h. Xem sau8 và sau16 ở phần Bộ nhớ. INC AL dài 2 byte (3 chu kỳ), INC AX chỉ 1 byte (2 chu kỳ). Đoán trước: sau INC AL, AX bằng bao nhiêu? Đáp án 0000h."}, {"label": "Lỗi: MOV AL, BX khác kích thước", "code": "; Lỗi: chép thanh ghi 16 bit vào thanh ghi 8 bit\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     BX, 0141H               ; BH = 01h, BL = 41h ('A')\n        MOV     AL, BX                  ; lỗi: AL 8 bit, BX 16 bit\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: AL 8 bit, BX 16 bit, hai toán hạng phải cùng kích thước. Trình dịch dừng ở dòng 7 và chương trình không chạy. Sửa: MOV AL, BL (lấy nửa thấp của BX, AL = 41h, in chữ A)."}, {"label": "Ví dụ: CX đếm, DL giữ ký tự, AH chọn hàm", "code": "; Ví dụ 4: mỗi thanh ghi một vai trò\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     CX, 5                   ; CX: số lần lặp\n        MOV     DL, 'A'                 ; DL: ký tự cần in\nlap:\n        MOV     AH, 02H                 ; AH: số hiệu hàm DOS\n        INT     21H                     ; in ký tự trong DL\n        INC     DL                      ; ký tự kế tiếp\n        LOOP    lap                     ; CX = CX - 1, khác 0 thì quay lại\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Ba thanh ghi, ba vai trò: CX đếm số lần cho LOOP, DL giữ ký tự cho hàm 02h, AH chọn hàm DOS. Bấm Từng bước để thấy CX giảm 5, 4, 3, 2, 1, 0 và DL tăng từ 41h tới 45h. Màn hình: ABCDE. Đoán trước: tới LOOP lần đầu, lệnh có nhảy không? Đáp án có (CX = 4 sau khi giảm)."}, {"label": "Ví dụ: SI và DI trỏ vào bộ nhớ", "code": "; Ví dụ 5: SI và DI trỏ vào bộ nhớ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nnguon   DB      'XYZ'\ndich    DB      '---$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET nguon        ; SI = 0000h\n        MOV     DI, OFFSET dich         ; DI = 0003h\n        MOV     CX, 3\nchep:\n        MOV     AL, [SI]                ; đọc ô DS:SI\n        MOV     [DI], AL                ; ghi ô DS:DI\n        INC     SI                      ; trỏ sang byte kế tiếp\n        INC     DI\n        LOOP    chep\n        MOV     DX, OFFSET dich\n        MOV     AH, 09H                 ; in chuỗi DS:DX tới dấu $\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "SI trỏ vào nguon, DI trỏ vào dich. Mỗi vòng: đọc ô DS:SI vào AL, ghi AL vào ô DS:DI, rồi dời cả hai con trỏ. Phần Bộ nhớ tô ô vừa đọc, vừa ghi; hình địa chỉ vật lý cho DS × 16 + SI. Cuối cùng in XYZ. Đoán trước: sau vòng đầu, DI bằng bao nhiêu? Đáp án 0004h."}, {"label": "Lỗi: AX không làm con trỏ được", "code": "; Lỗi: AX không dùng làm con trỏ được\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DB      '7'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, OFFSET so\n        MOV     DL, [AX]                ; lỗi: chỉ BX, BP, SI, DI làm địa chỉ\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: AX không có trong 8 dạng địa chỉ của 8086 (chỉ BX, BP, SI, DI). Trình dịch báo ở dòng 11. Sửa: MOV BX, OFFSET so rồi MOV DL, [BX]; chương trình in 7."}, {"label": "Ví dụ: chọn thanh ghi cho mã ngắn", "code": "; Ví dụ 7: chọn thanh ghi để mã ngắn và nhanh\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nx       DB      7\ny       DB      ?\nz       DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n; Cách 1: thanh ghi bất kỳ, lệnh tổng quát\n        MOV     CX, 0                   ; 3 byte, 4 chu kỳ\n        ADD     CX, 1                   ; 3 byte, 4 chu kỳ\n        MOV     BL, x                   ; 4 byte, 8 + 6 = 14 chu kỳ\n        MOV     y, BL                   ; 4 byte, 9 + 6 = 15 chu kỳ\n; Cách 2: cùng việc, dạng ngắn\n        XOR     AX, AX                  ; 2 byte, 3 chu kỳ\n        INC     AX                      ; 1 byte, 2 chu kỳ\n        MOV     AL, x                   ; 3 byte, 10 chu kỳ (dạng của AL)\n        MOV     z, AL                   ; 3 byte, 10 chu kỳ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Hai cách cùng kết quả: y = z = 7. Ở phần Mã máy và chu kỳ, cộng cột chu kỳ và byte: cách 1 (CX, BL) 37 chu kỳ, 14 byte; cách 2 (AX, AL) 25 chu kỳ, 9 byte. Đoán trước: MOV AL, x dài mấy byte? Đáp án 3 (A0 00 00)."}];
const sim5=makeX86Sim(document.getElementById("x86-l5"),{id:"s5",presets:P5,file:"BAI5.ASM"});
makeX86Ex(document.getElementById("ex-l5"),sim5,[{"t": "Hai nửa của DX", "d": "Đọc một phím k bằng INT 21h hàm 08h (không hiện). Kết thúc chương trình với DH = k và DL = k + 1 (ký tự đứng sau k trong bảng ASCII). Trước khi kết thúc, in ký tự trong DH rồi ký tự trong DL bằng INT 21h hàm 02h. Kết thúc bằng INT 21h hàm 4Ch. Phím là ký tự ASCII từ 20h tới 7Dh.", "start": "; Bài tập 1: DH = phím, DL = phím + 1, in DH rồi DL\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 08H                 ; đọc một phím, không hiện\n        INT     21H                     ; AL = mã ASCII của phím\n        MOV     DL, AL\n; Viết code ở đây: DH = phím, DL = phím + 1,\n; in ký tự trong DH rồi ký tự trong DL\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "A", "out": "AB", "regs": {"DX": 16706}}, {"in": "z", "out": "z{", "regs": {"DX": 31355}}, {"in": "0", "out": "01", "regs": {"DX": 12337}}, {"in": " ", "out": " !", "regs": {"DX": 8225}}, {"in": "}", "out": "}~", "regs": {"DX": 32126}}, {"in": "M", "out": "MN", "regs": {"DX": 19790}}]}, {"t": "Đảo ba phím bằng con trỏ", "d": "Đọc 3 phím bằng INT 21h hàm 08h. Ghi chúng vào mảng buf theo thứ tự ngược: phím thứ nhất vào buf+2, phím thứ hai vào buf+1, phím thứ ba vào buf. Sau đó in buf bằng INT 21h hàm 09h (buf đã có dấu $ ở cuối). Kết thúc bằng INT 21h hàm 4Ch. Phím không phải dấu $.", "start": "; Bài tập 2: ghi 3 phím vào buf theo thứ tự ngược\n; Bản này ghi theo thứ tự xuôi. Hãy sửa.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      3 DUP(0), '$'           ; giữ nguyên tên biến\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET buf          ; con trỏ bắt đầu ở buf\n        MOV     CX, 3\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        MOV     [SI], AL\n        INC     SI\n        LOOP    doc\n        MOV     DX, OFFSET buf\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "abc", "out": "cba", "mem": [{"at": "buf", "bytes": [99, 98, 97, 36]}]}, {"in": "123", "out": "321", "mem": [{"at": "buf", "bytes": [51, 50, 49, 36]}]}, {"in": "A B", "out": "B A", "mem": [{"at": "buf", "bytes": [66, 32, 65, 36]}]}, {"in": "xyz", "out": "zyx", "mem": [{"at": "buf", "bytes": [122, 121, 120, 36]}]}, {"in": "!?~", "out": "~?!", "mem": [{"at": "buf", "bytes": [126, 63, 33, 36]}]}, {"in": "aab", "out": "baa", "mem": [{"at": "buf", "bytes": [98, 97, 97, 36]}]}]}, {"t": "Ghép bốn phím nhanh hơn", "d": "Đọc lần lượt 4 phím k1, k2, k3, k4 bằng INT 21h hàm 08h. Kết thúc chương trình với BX = k1k2 (BH = k1, BL = k2) và CX = k3k4 (CH = k3, CL = k4). Code mẫu đã đúng nhưng cất từng phím vào ô nhớ rồi mới đọc lại nên chậm và dài. Viết lại để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: BX = k1k2, CX = k3k4\n; Bản này đúng nhưng cất từng phím vào ô nhớ rồi\n; mới đọc lại: chậm và dài. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nt1      DB      ?\nt2      DB      ?\nt3      DB      ?\nt4      DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        MOV     t1, AL                  ; cất phím 1\n        MOV     AH, 08H\n        INT     21H\n        MOV     t2, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     t3, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     t4, AL\n        MOV     BH, t1                  ; đọc lại từ bộ nhớ\n        MOV     BL, t2\n        MOV     CH, t3\n        MOV     CL, t4\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "ABCD", "regs": {"BX": 16706, "CX": 17220}}, {"in": "    ", "regs": {"BX": 8224, "CX": 8224}}, {"in": "~~~~", "regs": {"BX": 32382, "CX": 32382}}, {"in": "0123", "regs": {"BX": 12337, "CX": 12851}}, {"in": "z!a?", "regs": {"BX": 31265, "CX": 24895}}, {"in": "1111", "regs": {"BX": 12593, "CX": 12593}}], "perf": {"cycles": 300, "bytes": 34}}]);

makeQuiz("quiz5","score5",[{"q": "AX = 12FFh. Sau hai lệnh sau, AX bằng bao nhiêu?<pre class=\"mp-asm\">        INC     AL\n        MOV     AH, 0<\/pre>", "o": ["1300h: số nhớ từ AL được cộng sang AH", "0000h: INC AL cho AL = 00h, rồi AH bị ghi 0", "0100h: số nhớ vào AH rồi AH bị xóa", "1200h: MOV AH, 0 không đổi giá trị AX"], "a": 1, "e": "INC AL là phép tính 8 bit: AL = FFh + 1 = 00h, số nhớ không sang AH (AX = 1200h). Sau đó MOV AH, 0 ghi nửa cao: AX = 0000h. Lựa chọn 1300h là nhầm INC AL với INC AX."}, {"q": "Lệnh nào bị trình dịch 8086 báo lỗi?", "o": ["<code>MOV DL, [BX]<\/code>", "<code>MOV DL, [CX]<\/code>", "<code>MOV DL, [SI]<\/code>", "<code>MOV DL, [BP]<\/code>"], "a": 1, "e": "Chỉ BX, BP, SI, DI làm được địa chỉ trên 8086. CX là thanh ghi đếm, không có trong 8 dạng địa chỉ. [BP] hợp lệ nhưng mặc định thuộc đoạn SS."}, {"q": "Đoạn sau in ra gì?<pre class=\"mp-asm\">        MOV     CX, 3\n        MOV     DL, 'X'\nlap:    MOV     AH, 02H\n        INT     21H\n        INC     DL\n        LOOP    lap<\/pre>", "o": ["XXX: INC DL không đổi ký tự in", "XYZ[: LOOP chạy 4 lần vì kiểm CX trước khi giảm", "Không in gì: LOOP cần CX được đặt trong vòng lặp", "XYZ: LOOP dùng CX đếm 3 lần, DL tăng sau mỗi lần in"], "a": 3, "e": "LOOP giảm CX rồi nhảy khi CX khác 0: thân vòng chạy với CX = 3, 2, 1, tức 3 lần, in X, Y, Z. LOOP kiểm CX sau khi giảm nên không chạy lần thứ tư."}, {"q": "Cần đọc biến byte x vào một thanh ghi 8 bit, mã ngắn nhất. Chọn lệnh nào (theo bảng thời gian 8086, biến ở địa chỉ trực tiếp)?", "o": ["<code>MOV BL, x<\/code>: 3 byte, 10 chu kỳ", "<code>MOV DL, x<\/code>: 4 byte, 8 chu kỳ", "<code>MOV AL, x<\/code>: 3 byte, 10 chu kỳ", "<code>MOV CL, x<\/code>: 2 byte, 14 chu kỳ"], "a": 2, "e": "Chỉ AL/AX có dạng ngắn A0h (3 byte, 10 chu kỳ). Thanh ghi khác dùng dạng 8Ah + byte ModR/M + 2 byte địa chỉ: 4 byte, 8 + EA 6 = 14 chu kỳ."}, {"q": "SI đang bằng 0005h. Lệnh nào đọc <b>nội dung<\/b> byte tại độ lệch 0005h của đoạn DS vào AL?", "o": ["<code>MOV AL, [SI]<\/code>", "<code>MOV AL, SI<\/code>", "<code>MOV AL, OFFSET SI<\/code>", "<code>MOV AX, SI<\/code>"], "a": 0, "e": "Ngoặc vuông nghĩa là “ô nhớ có độ lệch bằng SI”. MOV AL, SI là lỗi dịch (8 và 16 bit); MOV AX, SI chỉ chép con số 0005h, không đọc bộ nhớ."}]);

